// Turn the location lookup into a multi-select form page.
// Input is either the /locations response ({ locations: [...] }) or an error item from the error output.
const form = $('Set Venue Configuration').first().json;
const query = String(form['Venue name'] || '').trim();
const group = String(form['Group'] || '').toLowerCase().startsWith('own') ? 'own' : 'competitor';
const choices = [];
const seen = new Set();
let failure = null;

for (const { json: j } of $input.all()) {
  if (j && j.error !== undefined && j.error !== null) {
    failure = typeof j.error === 'string' ? j.error : String(j.error.message || JSON.stringify(j.error));
    continue;
  }
  if (!j || !Array.isArray(j.locations)) {
    failure = 'Unexpected response (no locations array): ' + JSON.stringify(j || {}).slice(0, 150);
    continue;
  }
  for (const l of j.locations) {
    if (!l || l.id === undefined || l.id === null || seen.has(String(l.id))) continue;
    seen.add(String(l.id));
    choices.push({ id: Number(l.id), name: String(l.name || l.id), label: `${l.name || l.id} (ID ${l.id})` });
  }
}

if (choices.length === 0) {
  return [{ json: failure !== null
    ? { status: 'failed', query, message: failure.slice(0, 200) }
    : { status: 'none', query } }];
}

return [{
  json: {
    status: 'found',
    query,
    group,
    choices: choices.slice(0, 30),
    formFields: [{
      fieldLabel: 'Venues',
      fieldType: 'dropdown',
      multiselect: true,
      requiredField: true,
      fieldOptions: { values: choices.slice(0, 30).map(c => ({ option: c.label })) }
    }]
  }
}];

// Map the selected labels back to location IDs and build rows for the Venues tab.
// Only setup columns are written, so the sampling state of an existing venue is kept.
const raw = $json['Venues'];
const selected = Array.isArray(raw) ? raw : (raw ? [raw] : []);
const plan = $('Build Venue Selection Form').first().json;
const now = new Date().toISOString();

const rows = (plan.choices || [])
  .filter(c => selected.includes(c.label))
  .map(c => ({
    json: {
      'Venue ID': c.id,
      'Venue': c.name,
      'Group': plan.group,
      'Search Query': plan.query,
      'Active': 'yes',
      'Added At': now
    }
  }));

if (rows.length === 0) {
  throw new Error('No venue selected. Go back and pick at least one location.');
}
return rows;

