// Turn every active row of the Venues tab into one sample job and reset the per-run state.
// If no venue is set up yet, send one reminder (max once per 24 h on scheduled runs).
const cfg = $('Set Venue Configuration').first().json;
const state = $getWorkflowStaticData('global');
const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const inactive = ['no', 'false', '0', 'off', 'paused'];

state.runAbort = false;
state.runAbortReason = '';
// A low quota seen in an earlier run blocks searches only until the quota resets.
const resetMs = Date.parse(state.quotaReset || '');
if (!isNaN(resetMs) && resetMs <= Date.now()) state.quotaRemaining = null;

const seen = new Set();
const jobs = [];
for (const { json: r } of $input.all()) {
  const id = String((r || {})['Venue ID'] ?? '').trim();
  if (!id || seen.has(id)) continue;
  if (inactive.includes(String(r['Active'] ?? 'yes').trim().toLowerCase())) continue;
  seen.add(id);
  jobs.push({
    venueId: id,
    venueName: String(r['Venue'] || id),
    group: String(r['Group'] || '').toLowerCase().startsWith('own') ? 'own' : 'competitor',
    lastPostAt: String(r['Last Post At'] || '').trim()
  });
}

if (jobs.length > 0) {
  const maxVenues = Math.max(1, Math.floor(num(cfg.maxVenues, 15)));
  const dropped = Math.max(0, jobs.length - maxVenues);
  return jobs.slice(0, maxVenues).map(j => ({ json: { setupNeeded: false, droppedVenues: dropped, ...j } }));
}

const isManual = $execution.mode === 'manual';
const last = Date.parse(state.lastSetupReminder || '');
if (!isManual && !isNaN(last) && Date.now() - last < 24 * 3600 * 1000) return [];
if (!isManual) state.lastSetupReminder = new Date().toISOString();
const where = /^https?:\/\//.test(cfg.setupFormUrl || '')
  ? `Add venues here: ${cfg.setupFormUrl}`
  : 'Open the "Venue Setup Form" node in n8n and use its production URL to add venues.';
return [{ json: { setupNeeded: true, chatId: cfg.telegramChatId,
  text: `ℹ️ <b>No active venues yet</b>\n\nThe venue benchmark has nothing to sample. ${where}` } }];

// Skip the request when a fatal API error happened earlier in this run or the daily quota is low.
const cfg = $('Set Venue Configuration').first().json;
const state = $getWorkflowStaticData('global');
const job = { ...$json };
const minQuota = Number(cfg.minQuotaRemaining);

if (state.runAbort) {
  job.skipped = true;
  job.skipReason = state.runAbortReason || 'skipped after a fatal API error earlier in this run';
} else if (typeof state.quotaRemaining === 'number' && Number.isFinite(minQuota) && state.quotaRemaining < minQuota) {
  job.skipped = true;
  job.skipReason = `daily quota is low (${state.quotaRemaining} left, minimum ${minQuota})`;
}
return [{ json: job }];

// Turn one page of posts into a posting-rate estimate for this venue.
// rate = (k - 1) / hours between now and the k-th newest post, with k = postsPerSample
// (or fewer when the lookback cap cuts the list). Fewer than minPostsForRate posts = "low" volume.
const cfg = $('Set Venue Configuration').first().json;
const state = $getWorkflowStaticData('global');
const job = $('Prepare Venue Sample Request').last().json;
const res = $input.first().json || {};
const headers = res.headers || {};
const body = res.body;
const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const now = Date.now();

// Remember the quota headers for the rest of this run and for later runs.
const rem = headers['x-ratelimit-remaining'];
if (rem !== undefined && rem !== '' && Number.isFinite(Number(rem))) state.quotaRemaining = Number(rem);
if (headers['x-ratelimit-reset']) state.quotaReset = String(headers['x-ratelimit-reset']);

const base = { _kind: 'sample', venueId: job.venueId, lastPostAt: job.lastPostAt };
if (!body || !Array.isArray(body.results)) {
  return [{ json: { ...base, status: 'error', error: 'Unexpected response (no results array): ' + JSON.stringify(body || {}).slice(0, 200) } }];
}

const k = Math.max(2, Math.floor(num(cfg.postsPerSample, 20)));
const minPosts = Math.max(2, Math.floor(num(cfg.minPostsForRate, 3)));
const capHours = Math.max(1, num(cfg.lookbackCapHours, 72));

// Sort newest first ourselves and ignore posts without a valid date or dated in the future.
const posts = body.results
  .filter(p => p && p.url)
  .map(p => ({ p, t: Date.parse(p.posted_at) }))
  .filter(x => !isNaN(x.t) && x.t <= now + 5 * 60 * 1000)
  .sort((a, b) => b.t - a.t);
const used = posts.filter(x => now - x.t <= capHours * 3600 * 1000).slice(0, k);
const n = used.length;

let status, rate, windowHours;
if (n >= minPosts) {
  status = 'ok';
  windowHours = Math.max((now - used[n - 1].t) / 3600000, 1 / 60);
  rate = (n - 1) / windowHours;
} else {
  status = 'low';
  windowHours = capHours;
  rate = n / capHours;
}

// Posts newer than the venue's watermark are stored for the weekly report (author names are not stored).
const wm = Date.parse(job.lastPostAt || '');
const fresh = posts.filter(x => isNaN(wm) || x.t > wm).slice(0, k).map(x => ({
  url: String(x.p.url),
  postedAt: new Date(x.t).toISOString(),
  isVideo: x.p.is_video === true,
  likes: typeof x.p.likes === 'number' ? x.p.likes : null,
  hashtags: Array.isArray(x.p.hashtags) ? x.p.hashtags.filter(h => typeof h === 'string').join(' ') : '',
  caption: String(x.p.caption || '').slice(0, 500)
}));

return [{
  json: {
    ...base,
    status,
    rate: Math.round(rate * 1000) / 1000,
    postsUsed: n,
    windowHours: Math.round(windowHours * 100) / 100,
    distinctAuthors: new Set(used.map(x => x.p.author_id || x.p.author).filter(Boolean)).size,
    newestPostAt: posts.length ? new Date(posts[0].t).toISOString() : job.lastPostAt,
    posts: fresh
  }
}];

// Turn a failed request into a marker item so the loop finishes and problems are reported together.
// 401, 403 and 429 skip the remaining venues of this run (the same error would repeat).
const job = $('Prepare Venue Sample Request').last().json;
const state = $getWorkflowStaticData('global');
const err = $input.first().json.error;
const message = String((err && (err.message || err.description)) || (typeof err === 'string' ? err : JSON.stringify(err || {})));
const m = /\b(400|401|403|429|500|502|503|504)\b/.exec(message);
const status = m ? Number(m[1]) : null;
const advice = {
  400: 'RecentReborn rejected the request. Check the Venue ID in the Venues tab.',
  401: 'The API key is missing, revoked or wrong. Update the HTTP Header Auth credential.',
  403: 'Your RecentReborn plan does not include API access.',
  429: 'The daily quota is used up or more than 20 requests were sent in one minute. Sampling resumes after the reset.'
}[status] || 'Temporary problem at RecentReborn or Instagram. The next run tries again (failed searches cost nothing).';
const fatal = [401, 403, 429].includes(status);
if (fatal) {
  state.runAbort = true;
  state.runAbortReason = `skipped after HTTP ${status} on an earlier venue`;
}
return [{ json: { _kind: 'sample', venueId: job.venueId, lastPostAt: job.lastPostAt, status: 'error',
  httpStatus: status, fatal, advice, error: message.slice(0, 300) } }];

// Runs once after the loop. Builds ONE summary item with:
//   sampleRows -> Samples tab (append, one row per venue and run)
//   postRows   -> Posts tab (append, posts newer than each venue's watermark)
//   venueRows  -> Venues tab (update watermark and last status)
//   alerts, counts and whether the weekly report is due
const cfg = $('Set Venue Configuration').first().json;
const state = $getWorkflowStaticData('global');
const jobs = $('Schedule Sampling Jobs').all().map(i => i.json);
const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const now = new Date();
const nowIso = now.toISOString();
const isManual = $execution.mode === 'manual';

// Local time in the configured timezone (falls back to UTC if the name is invalid).
let tz = String(cfg.timezone || 'UTC');
try { new Intl.DateTimeFormat('en-GB', { timeZone: tz }); } catch (e) { tz = 'UTC'; }
const parts = {};
for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', weekday: 'short', hourCycle: 'h23' }).formatToParts(now)) parts[p.type] = p.value;
const hour = Number(parts.hour);
const weekday = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].indexOf(parts.weekday) + 1;
const today = `${parts.year}-${parts.month}-${parts.day}`;
const daypart = hour < 6 ? 'night' : hour < 12 ? 'morning' : hour < 18 ? 'afternoon' : 'evening';

// Skipped jobs come back from the IF node as plain jobs, measured ones as _kind 'sample'.
const byVenue = {};
for (const { json: it } of $input.all()) if (it && it.venueId !== undefined) byVenue[String(it.venueId)] = it;

const sampleRows = [], postRows = [], venueRows = [];
const counts = { venues: jobs.length, ok: 0, low: 0, error: 0, skipped: 0, newPosts: 0 };
const fatal = {};
let skipReason = '';

for (const job of jobs) {
  const it = byVenue[String(job.venueId)] || { skipped: true, skipReason: 'no result returned' };
  const row = { 'Sampled At': nowIso, 'Local Time': `${today} ${parts.hour}:00`, 'Daypart': daypart,
    'Venue ID': job.venueId, 'Venue': job.venueName, 'Group': job.group };
  const empty = { 'Posts Used': '', 'Window Hours': '', 'Rate Per Hour': '', 'Distinct Authors': '' };

  if (it.skipped === true) {
    counts.skipped++;
    skipReason = it.skipReason || skipReason;
    sampleRows.push({ ...row, 'Status': 'skipped', ...empty, 'Note': String(it.skipReason || '').slice(0, 200) });
    venueRows.push({ 'Venue ID': job.venueId, 'Last Status': 'skipped' });
    continue;
  }
  if (it.status === 'error') {
    counts.error++;
    if (it.fatal) fatal[it.httpStatus] = it.advice;
    sampleRows.push({ ...row, 'Status': 'error', ...empty, 'Note': String(it.error || '').slice(0, 200) });
    venueRows.push({ 'Venue ID': job.venueId, 'Last Sampled At': nowIso, 'Last Status': 'error' });
    continue;
  }

  counts[it.status] = (counts[it.status] || 0) + 1;
  sampleRows.push({ ...row, 'Status': it.status, 'Posts Used': it.postsUsed, 'Window Hours': it.windowHours,
    'Rate Per Hour': it.rate, 'Distinct Authors': it.distinctAuthors, 'Note': '' });
  const seen = new Set();
  for (const p of it.posts || []) {
    if (seen.has(p.url)) continue;
    seen.add(p.url);
    postRows.push({ 'Post URL': p.url, 'Posted At': p.postedAt, 'Venue ID': job.venueId, 'Venue': job.venueName,
      'Group': job.group, 'Format': p.isVideo ? 'Reel' : 'Photo', 'Likes': p.likes === null ? '' : p.likes,
      'Hashtags': p.hashtags, 'Caption': p.caption, 'Sampled At': nowIso });
  }
  venueRows.push({ 'Venue ID': job.venueId, 'Last Post At': it.newestPostAt || job.lastPostAt || '',
    'Last Sampled At': nowIso, 'Last Rate Per Hour': it.rate, 'Last Status': it.status });
}
counts.newPosts = postRows.length;

const alerts = [];
for (const [status, advice] of Object.entries(fatal)) alerts.push({ key: 'http_' + status, text: `HTTP ${status} from RecentReborn. ${advice}` });
if (counts.skipped > 0) alerts.push({ key: 'skipped', text: `${counts.skipped} of ${counts.venues} venues were not sampled: ${skipReason}.` });
if (jobs.length && jobs[0].droppedVenues > 0) alerts.push({ key: 'dropped', text: `${jobs[0].droppedVenues} active venues are above maxVenues and were not sampled. Raise maxVenues or pause venues.` });

// Weekly report: on the configured weekday from the configured hour, once per day.
// Catch-up: if the last report is more than 8 days old (missed runs), send it now.
const lastAt = Date.parse(state.lastReportAt || '');
let reportDue;
if (isManual) reportDue = cfg.sendReportOnManualRun === true;
else reportDue = (weekday === num(cfg.reportWeekday, 1) && hour >= num(cfg.reportHour, 8) && state.lastReportLocalDate !== today)
  || (!isNaN(lastAt) && now.getTime() - lastAt > 8 * 86400 * 1000);

return [{ json: { sampleRows, postRows, venueRows, counts, alerts, reportDue, today,
  quotaRemaining: typeof state.quotaRemaining === 'number' ? state.quotaRemaining : null } }];

