// Build the weekly comparison from the Samples and Posts tabs (one item for the report step).
const cfg = $('Set Venue Configuration').first().json;
const venues = $('Schedule Sampling Jobs').all().map(i => i.json);
const samples = $('Read Sample Log from Sheets').all().map(i => i.json || {});
const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const t = v => Date.parse(String(v || ''));
const now = Date.now();
const days = Math.max(1, num(cfg.reportWindowDays, 7));
const from = now - days * 86400 * 1000;
const prevFrom = now - 2 * days * 86400 * 1000;
const median = a => { if (!a.length) return null; const b = [...a].sort((x, y) => x - y); const m = Math.floor(b.length / 2); return b.length % 2 ? b[m] : (b[m - 1] + b[m]) / 2; };
const ratesOf = rows => rows.filter(r => ['ok', 'low'].includes(String(r['Status']))).map(r => Number(r['Rate Per Hour'])).filter(Number.isFinite);
const likesOf = p => (p['Likes'] === '' || p['Likes'] === null || p['Likes'] === undefined || !Number.isFinite(Number(p['Likes']))) ? null : Number(p['Likes']);
const capPerVenue = Math.max(0, Math.floor(num(cfg.aiCaptionsPerVenue, 15)));
const topN = Math.max(1, Math.floor(num(cfg.topPostsPerGroup, 3)));

// Posts of this window, deduplicated by venue and URL (a failed watermark update can store a post twice).
const seen = new Set();
const posts = $input.all().map(i => i.json || {}).filter(p => {
  const key = String(p['Venue ID']) + '|' + String(p['Post URL']);
  if (!p['Post URL'] || t(p['Posted At']) < from || seen.has(key)) return false;
  seen.add(key);
  return true;
}).sort((a, b) => t(b['Posted At']) - t(a['Posted At']));

const stats = venues.map(v => {
  const id = String(v.venueId);
  const mine = samples.filter(r => String(r['Venue ID']) === id);
  const cur = mine.filter(r => t(r['Sampled At']) >= from);
  const prev = mine.filter(r => { const x = t(r['Sampled At']); return x >= prevFrom && x < from; });
  const curRates = ratesOf(cur);
  const med = median(curRates);
  const prevMed = median(ratesOf(prev));
  // Time of day: only short windows (6 h or less) describe the daypart they were taken in.
  const byPart = {};
  for (const r of cur) {
    if (r['Status'] !== 'ok' || !(Number(r['Window Hours']) <= 6)) continue;
    (byPart[r['Daypart']] = byPart[r['Daypart']] || []).push(Number(r['Rate Per Hour']));
  }
  const busiest = Object.entries(byPart).filter(([, a]) => a.length >= 2)
    .map(([part, a]) => ({ part, rate: median(a) })).sort((a, b) => b.rate - a.rate)[0] || null;
  const vPosts = posts.filter(p => String(p['Venue ID']) === id);
  const tags = {};
  for (const p of vPosts) for (const h of String(p['Hashtags'] || '').toLowerCase().split(/\s+/).filter(Boolean)) tags[h] = (tags[h] || 0) + 1;
  return {
    venueId: id, venue: v.venueName, group: v.group,
    samples: cur.length,
    measured: curRates.length,
    gaps: cur.filter(r => ['error', 'skipped'].includes(String(r['Status']))).length,
    lowVolume: curRates.length > 0 && !cur.some(r => r['Status'] === 'ok'),
    medianRate: med,
    change: med !== null && prevMed ? (med - prevMed) / prevMed : null,
    busiest,
    storedPosts: vPosts.length,
    reelsShare: vPosts.length ? vPosts.filter(p => p['Format'] === 'Reel').length / vPosts.length : null,
    topTags: Object.entries(tags).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([h]) => h),
    captions: vPosts.filter(p => String(p['Caption'] || '').trim()).slice(0, capPerVenue)
      .map(p => ({ url: p['Post URL'], text: String(p['Caption']).replace(/\s+/g, ' ').slice(0, 200) }))
  };
});

const total = stats.reduce((a, x) => a + (x.medianRate || 0), 0);
for (const x of stats) x.share = total > 0 && x.medianRate !== null ? x.medianRate / total : null;
const groupRate = g => stats.filter(x => x.group === g && x.medianRate !== null).reduce((a, x) => a + x.medianRate, 0);
const groupOf = Object.fromEntries(stats.map(x => [x.venueId, x.group]));
const top = g => posts.filter(p => groupOf[String(p['Venue ID'])] === g)
  .sort((a, b) => (likesOf(b) ?? -1) - (likesOf(a) ?? -1)).slice(0, topN)
  .map(p => ({ url: p['Post URL'], venue: p['Venue'], likes: likesOf(p), format: p['Format'] }));

// One batched AI prompt for the whole report. Captions get a global index so the answer can point at posts.
const captionIndex = [];
const payload = stats.map(x => ({ venue_id: x.venueId, venue: x.venue, group: x.group,
  captions: x.captions.map(c => { captionIndex.push({ url: c.url, venueId: x.venueId }); return { i: captionIndex.length - 1, text: c.text }; }) }));
const shape = '{"venues":[{"venue_id":"<id>","themes":["<up to 3 short themes>"],"tone":"positive|mixed|negative|neutral"}],"watch_posts":[{"i":0,"reason":"<short reason>"}],"summary":"<2 to 3 sentences>"}';
const prompt = `${cfg.aiInstructions}\n\nReturn only JSON in exactly this shape:\n${shape}\n\nVenues and captions:\n${JSON.stringify(payload)}`;

return [{ json: {
  days,
  stats: stats.map(({ captions, ...rest }) => rest),
  ownRate: groupRate('own'),
  competitorRate: groupRate('competitor'),
  top: { own: top('own'), competitor: top('competitor') },
  captionIndex,
  prompt,
  sendToAi: cfg.useAi === true && captionIndex.length > 0 ? 'yes' : 'no'
} }];

// Validate the AI output (hashtags are used if it is missing or malformed) and write the weekly report.
const cfg = $('Set Venue Configuration').first().json;
const w = $('Compute Weekly Metrics').first().json;
const s = $('Proceed with Venue Updates').first().json;
const esc = v => String(v === null || v === undefined ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const pct = x => (x === null || x === undefined) ? 'n/a' : (x > 0 && x < 0.01) ? '<1%' : Math.round(x * 100) + '%';
const fmtRate = x => x === null || x === undefined ? 'n/a' : x >= 10 ? x.toFixed(0) : x >= 1 ? x.toFixed(1) : x.toFixed(2);
const TONES = ['positive', 'mixed', 'negative', 'neutral'];

let ai = null;
let aiNote = '';
let aiRan = false;
try { aiRan = $('AI-Caption Summary').isExecuted; } catch (e) { /* not executed */ }
if (aiRan) {
  const out = $('AI-Caption Summary').first().json || {};
  const raw = out.text ?? out.response ?? out.output ?? '';
  const txt = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const a = txt.indexOf('{'), b = txt.lastIndexOf('}');
  if (a >= 0 && b > a) { try { const o = JSON.parse(txt.slice(a, b + 1)); if (o && Array.isArray(o.venues)) ai = o; } catch (e) { /* malformed */ } }
  if (!ai) aiNote = 'AI summary unavailable (output missing or not valid JSON). Top hashtags are shown instead.';
}
const aiVenue = {};
if (ai) for (const v of ai.venues) {
  if (!v || v.venue_id === undefined) continue;
  aiVenue[String(v.venue_id)] = {
    themes: (Array.isArray(v.themes) ? v.themes : []).filter(x => typeof x === 'string' && x.trim()).slice(0, 3),
    tone: TONES.includes(v.tone) ? v.tone : null
  };
}
const watch = [];
if (ai && Array.isArray(ai.watch_posts)) for (const wp of ai.watch_posts.slice(0, 5)) {
  const ref = Number.isInteger(wp && wp.i) ? w.captionIndex[wp.i] : null;
  const venue = ref && w.stats.find(x => x.venueId === ref.venueId);
  if (venue && venue.group === 'own') watch.push({ url: ref.url, venue: venue.venue, reason: String(wp.reason || '').slice(0, 150) });
}

const lines = [`📊 <b>Weekly venue report</b> (last ${w.days} days)`];
if (w.ownRate > 0 || w.competitorRate > 0) {
  const share = w.ownRate + w.competitorRate > 0 ? w.ownRate / (w.ownRate + w.competitorRate) : null;
  lines.push(`Your venues: <b>${pct(share)}</b> of posting activity (${fmtRate(w.ownRate)} posts/h vs ${fmtRate(w.competitorRate)} posts/h for competitors)`);
}
if (ai && typeof ai.summary === 'string' && ai.summary.trim()) lines.push('', esc(ai.summary.trim().slice(0, 600)));

lines.push('', '<b>Ranking by median posts per hour</b>');
const ranked = [...w.stats].sort((a, b) => (b.medianRate ?? -1) - (a.medianRate ?? -1));
let rank = 0;
for (const x of ranked) {
  const icon = x.group === 'own' ? '🏠' : '⚔️';
  if (x.medianRate === null) { lines.push(`${icon} <b>${esc(x.venue)}</b>: no successful samples`); continue; }
  rank++;
  let l = `${rank}. ${icon} <b>${esc(x.venue)}</b>: ${x.lowVolume ? 'about ' : ''}${fmtRate(x.medianRate)}/h, ${pct(x.share)} share`;
  if (x.change !== null) l += ` (${x.change >= 0 ? '+' : ''}${Math.round(x.change * 100)}% vs previous period)`;
  const extra = [];
  if (x.lowVolume) extra.push('low volume');
  if (x.busiest) extra.push(`busiest: ${x.busiest.part}`);
  if (x.reelsShare !== null) extra.push(`${pct(x.reelsShare)} Reels`);
  const av = aiVenue[x.venueId];
  if (av && av.themes.length) extra.push(`themes: ${av.themes.join(', ')}${av.tone ? ` (${av.tone})` : ''}`);
  else if (x.topTags.length) extra.push('tags: ' + x.topTags.map(h => '#' + h).join(' '));
  if (extra.length) l += `\n    ${esc(extra.join(' · '))}`;
  lines.push(l);
}

if (watch.length) {
  lines.push('', '<b>Posts at your venues to look at</b>');
  for (const p of watch) lines.push(`• <a href="${esc(p.url)}">${esc(p.venue)}</a>: ${esc(p.reason)}`);
}
for (const [g, label] of [['own', 'Top posts at your venues'], ['competitor', 'Top posts at competitors']]) {
  if (!w.top[g].length) continue;
  lines.push('', `<b>${label}</b>`);
  for (const p of w.top[g]) lines.push(`• <a href="${esc(p.url)}">${esc(p.format)}</a> at ${esc(p.venue)}${p.likes !== null ? ` · ${p.likes} likes` : ''}`);
}

const totalSamples = w.stats.reduce((a, x) => a + x.samples, 0);
const gaps = w.stats.reduce((a, x) => a + x.gaps, 0);
lines.push('', `<i>Samples: ${totalSamples - gaps} measured, ${gaps} failed or skipped. Rates are estimates from the newest posts at each sample, not total counts.${s.quotaRemaining !== null ? ` Quota left today: ${s.quotaRemaining}.` : ''}</i>`);
if (aiNote) lines.push(`<i>${esc(aiNote)}</i>`);
for (const a of s.alerts || []) lines.push(`⚠️ ${esc(a.text)}`);

// Telegram allows 4096 characters per message. Split on line breaks.
const chunks = [];
let cur = '';
for (const l of lines) {
  if (cur && (cur + '\n' + l).length > 3500) { chunks.push(cur); cur = l; }
  else cur = cur ? cur + '\n' + l : l;
}
if (cur) chunks.push(cur);
return chunks.map(text => ({ json: { chatId: cfg.telegramChatId, text } }));

// Sample runs without a report only send urgent problems, each at most once per 12 h.
// Manual runs also get a short health message, so a test run always shows a result.
const cfg = $('Set Venue Configuration').first().json;
const s = $('Proceed with Venue Updates').first().json;
const state = $getWorkflowStaticData('global');
const esc = v => String(v === null || v === undefined ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const isManual = $execution.mode === 'manual';
state.alertSentAt = state.alertSentAt || {};

const lines = [];
for (const a of s.alerts || []) {
  const last = Date.parse(state.alertSentAt[a.key] || '');
  if (!isManual && !isNaN(last) && Date.now() - last < 12 * 3600 * 1000) continue;
  state.alertSentAt[a.key] = new Date().toISOString();
  lines.push('• ' + esc(a.text));
}

let text = lines.length ? `⚠️ <b>Venue sampling problem</b>\n\n${lines.join('\n')}` : '';
if (isManual) {
  const c = s.counts;
  text = (text ? text + '\n\n' : '') + `✅ <b>Test run finished</b>\n${c.venues} venues: ${c.ok} measured, ${c.low} low volume, ${c.error} failed, ${c.skipped} skipped. ${c.newPosts} new posts stored.`
    + (s.quotaRemaining !== null ? `\nQuota left today: ${s.quotaRemaining}` : '')
    + '\nSet sendReportOnManualRun to true in the config node to preview the weekly report.';
}
if (!text) return [];
return [{ json: { chatId: cfg.telegramChatId, text } }];

// Remember that this week's report went out. Runs only after Telegram accepted the messages.
const s = $('Proceed with Venue Updates').first().json;
const state = $getWorkflowStaticData('global');
if (s.reportDue && $execution.mode !== 'manual') {
  state.lastReportAt = new Date().toISOString();
  state.lastReportLocalDate = s.today;
}
return [{ json: { reportSent: s.reportDue === true, counts: s.counts } }];
